"""Render the fixed EP2 real-loader dropout audit without external dependencies."""
import argparse,base64,json,pathlib
p=argparse.ArgumentParser();p.add_argument('--root',type=pathlib.Path,required=True);a=p.parse_args();root=a.root
rows=[json.loads(x) for x in (root/'samples.jsonl').read_text().splitlines()]
assert len(rows)==100
images={path:'data:image/jpeg;base64,'+base64.b64encode((root/path).read_bytes()).decode() for r in rows for path in r['current_images'].values()}
summary=json.loads((root/'summary.json').read_text());mapping=json.loads((root/'mapping.json').read_text())
counts={key:sum(bool(r['augmentation'][key]) for r in rows) for key in ['memory_dropout_draw','memory_dropout_applied','subtask_dropout_applied']}
counts['both_draws']=sum(r['augmentation']['memory_dropout_draw'] and r['augmentation']['subtask_dropout_draw'] for r in rows)
payload=json.dumps(dict(rows=rows,images=images,summary=summary,mapping=mapping,counts=counts),ensure_ascii=False).replace('</',r'<\/')
html=r'''<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EP2 · Memory / Subtask dropout</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:#172b3a;font:15px system-ui}header{background:#12394a;color:white;padding:24px 3vw}main{padding:20px 3vw}h1{font-size:25px}p{line-height:1.7}section,.box{padding:18px;background:white;border:1px solid #d8e2ec;border-radius:10px;margin:14px 0}.notice{background:#fff6dd;padding:14px;border-radius:8px;line-height:1.7}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.views{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}img{width:100%;border-radius:6px}figure{margin:0}figcaption{font-size:12px;color:#567}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.65 ui-monospace,monospace;background:#f6f8fb;padding:13px;border-radius:6px}nav{position:sticky;top:0;background:#f3f6faf5;display:flex;gap:12px;align-items:center;padding:12px 0}input{flex:1;min-width:35px}button,select{padding:9px;border:1px solid #ccd8e1;border-radius:7px;background:white}strong{color:#087d7d}.badge{padding:9px;background:#eaf5f2;border-radius:6px}.empty{color:#98711e}.item{margin:10px 0;line-height:1.6}.item b{display:block;color:#517084;font-size:12px}details{margin-top:12px}summary{cursor:pointer;padding:10px}@media(max-width:750px){.grid{grid-template-columns:1fr}.views{grid-template-columns:1fr 1fr}main{padding:12px}header{padding:18px}}</style>
<header><select id="lang"><option value="zh">中文</option><option value="en">English</option><option value="ja">日本語</option></select><h1>2026.03.16_twist_many · 平台 EP2</h1><p id="intro"></p><small id="source"></small></header><main><div class="box" id="stats"></div><div class="notice" id="note"></div><nav><button id="prev">←</button><span id="position"></span><input type="range" id="slider" min="0" max="99"><button id="next">→</button></nav><h2 id="frame"></h2><div class="views" id="views"></div><div class="box"><h3 id="annotationTitle"></h3><pre id="annotation"></pre></div><div class="grid"><section><h3 id="beforeTitle"></h3><div id="before"></div><details open><summary>Prompt</summary><pre id="beforePrompt"></pre></details></section><section><h3 id="afterTitle"></h3><div id="after"></div><p class="badge" id="flags"></p><details open><summary>Prompt</summary><pre id="afterPrompt"></pre></details></section></div><section><h3 id="recordTitle"></h3><pre id="records"></pre><details><summary>Raw / 原始记录</summary><pre id="raw"></pre></details></section></main>
<script id="payload" type="application/json">PAYLOAD</script><script>
const d=JSON.parse(document.getElementById('payload').textContent),$=x=>document.getElementById(x);let i=0,lang='zh';
const T={zh:{intro:'真实 DataLoader · 100 帧输入核对。Memory 只丢最新一条完成记录；当前任务独立 dropout。没有按时间取旧记忆。',note:'本报告用逐帧人工标注构建 Memory，未调用 GPT，不能视为 GPT 准确率报告。标注未明确确认丢入垃圾桶或空手归位成功，因此不编造这些完成记录；标注切换到新目标瓶子时使用该瓶子的独立 Memory；这不是归位完成证明。上方四路图供检查；low-level 沿用三路相机。',before:'真实 DataLoader：dropout 前',after:'真实 DataLoader：dropout 后',annotation:'人工标注（bottle_state 是当前状态，不是 Memory）',records:'完成记录与本次删除项',empty:'（空）'},en:{intro:'100 real DataLoader samples. Drop only the latest completed memory record; independently drop the current task. No time-based old-memory selection.',note:'Memory comes from per-frame human annotations, not GPT. Missing confirmation of bin release or empty-handed home arrival is not invented. A newly annotated target bottle starts its own object-local memory; this does not confirm home arrival. Four cameras are shown for review; low-level keeps its three-camera configuration.',before:'Real DataLoader: before dropout',after:'Real DataLoader: after dropout',annotation:'Human annotation (bottle_state is not Memory)',records:'Completed records and removed item',empty:'(empty)'},ja:{intro:'実際の DataLoader 100フレーム。Memory は最新の完了記録のみ削除し、現在タスクは独立して dropout。過去時刻の記憶への置換はありません。',note:'逐フレームの人手ラベルに基づく Memory です。GPTの精度評価ではありません。ゴミ箱への解放・空手の帰位が明示されない場合、完了を捏造しません。新しい対象ボトルは独立した記憶で開始しますが、帰位完了を意味しません。画像は4視点、low-levelは元の3視点です。',before:'実 DataLoader：dropout 前',after:'実 DataLoader：dropout 後',annotation:'人手ラベル（bottle_state は Memory ではない）',records:'完了記録と削除項目',empty:'（空）'}};
function text(id,s){$(id).textContent=s}function state(id,s){$(id).replaceChildren();for(const k of ['bottle_description','memory','current_task']){let n=document.createElement('div'),b=document.createElement('b'),v=document.createElement('span');n.className='item';b.textContent=k;v.textContent=s[k]||T[lang].empty;if(!s[k])v.className='empty';n.append(b,v);$(id).append(n)}}
function show(){const r=d.rows[i],a=r.augmentation,t=T[lang];for(const [id,key]of [['intro','intro'],['note','note'],['beforeTitle','before'],['afterTitle','after'],['annotationTitle','annotation'],['recordTitle','records']])text(id,t[key]);text('source',d.mapping.project_id+' · LeRobot EP '+d.mapping.lerobot_episode_index+' · '+d.mapping.frames+' frames · '+d.mapping.revision);text('stats','Memory dropout = 20% · Subtask dropout = 20% · independent / 独立 / 独立抽選 ｜ 100 samples: memory draw '+d.counts.memory_dropout_draw+', actual removal '+d.counts.memory_dropout_applied+', subtask blank '+d.counts.subtask_dropout_applied+', both draws '+d.counts.both_draws);text('position',(i+1)+' /100');$('slider').value=i;text('frame','Frame '+r.frame_index+' · '+r.time_s.toFixed(3)+' s');$('views').replaceChildren();for(const [camera,path]of Object.entries(r.current_images)){let f=document.createElement('figure'),im=document.createElement('img'),c=document.createElement('figcaption');im.src=d.images[path];im.alt=camera;c.textContent=camera;f.append(im,c);$('views').append(f)}text('annotation',JSON.stringify(r.annotation,null,2));state('before',r.before_augmentation);state('after',r.actual_training_memory);text('beforePrompt',r.model_prompt_before_augmentation);text('afterPrompt',r.model_prompt);text('flags','Memory: '+a.memory_dropout_applied+' · Subtask: '+a.subtask_dropout_applied);text('records',JSON.stringify(a,null,2));text('raw',JSON.stringify(r,null,2))}
$('prev').onclick=()=>{i=Math.max(0,i-1);show()};$('next').onclick=()=>{i=Math.min(99,i+1);show()};$('slider').oninput=e=>{i=+e.target.value;show()};$('lang').onchange=e=>{lang=e.target.value;show()};show();
</script></html>'''.replace('PAYLOAD',payload)
(root/'review.html').write_text(html);(root/'dropout-counts.json').write_text(json.dumps(counts,indent=2));print(root/'review.html',len(html))
